/** Source: rayquaza_scene.c → Task_SetNextAnim */
export const Task_SetNextAnim: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  if (!rt.gPaletteFade.active)
      {
          if (sRayScene.endEarly == true)
          {
              task.func = (t) => Task_EndAfterFadeScreen(t, rt);
          }
          else
          {
              sRayScene.animId++;
              sRayScene.unk = 0;
              task.func = (t) => sTasksForAnimations(t, rt)[sRayScene.animId];
          }
      }
};

/** Source: rayquaza_scene.c → Task_HandleDuoFightPre */
export const Task_HandleDuoFightPre: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  const data = task.data;
      DuoFight_AnimateRain();
      if (!rt.gPaletteFade.active)
      {
          let frame = data[1];
          if (frame == 64)
          {
              DuoFight_Lightning1();
          }
          else if (frame == 144)
          {
              DuoFight_Lightning2();
          }
          else
          {
              switch (frame)
              {
              case 328:
                  DuoFightEnd(taskId, 0);
                  return;
              case 148:
                  DuoFight_LightningLong();
                  break;
              }
          }

          data[1]++;
      }
};

/** Source: rayquaza_scene.c → Task_DuoFightAnim */
export const Task_DuoFightAnim: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  const data = task.data;
      ScanlineEffect_Clear();
      InitDuoFightSceneBgs();
      LoadDuoFightSceneGfx();
      CpuFastFill16(0, gScanlineEffectRegBuffers, ((gScanlineEffectRegBuffers)?.length ?? 32));
      ScanlineEffect_SetParams(sScanlineParams_DuoFight_Clouds);
      data[1] = 0;
      data[1] = rt.CreateTask((t) => Task_DuoFight_AnimateClouds(t, rt), 0);
      if (sRayScene.animId == RAY_ANIM_DUO_FIGHT_PRE)
      {
          data[2] = DuoFightPre_CreateGroudonSprites();
          data[3] = DuoFightPre_CreateKyogreSprites();
          task.func = (t) => Task_HandleDuoFightPre(t, rt);
      }
      else
      {
          data[2] = DuoFight_CreateGroudonSprites();
          data[3] = DuoFight_CreateKyogreSprites();
          task.func = (t) => Task_HandleDuoFight(t, rt);
          StopMapMusic();
      }

      BlendPalettes(PALETTES_ALL, 0x10, RGB_BLACK);
      rt.BeginNormalPaletteFade("PALETTES_ALL", 0, 0x10, 0, "RGB_BLACK");
      /* noop SetVBlankCallback */;
      /* TODO sound PlaySE */;
};

