/** Source: rayquaza_scene.c → Task_HandleRayTakesFlight */
export const Task_HandleRayTakesFlight: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  const data = task.data;
      switch (data[0])
      {
      case 0:
           
          if (data[1] == 8)
          {
              rt.BeginNormalPaletteFade("PALETTES_ALL", 0, 0x10, 0, "RGB_BLACK");
              data[1] = 0;
              data[4] = 30;
              data[4] = 0;
              data[5] = 7;
              data[1] = 0;
              data[0]++;
          }
          else
          {
              data[1]++;
          }
          break;
      case 1:
           
          data[1] += data[4];
          data[4] += data[5];

          if (data[4] > 3)
              data[4] -= 3;

          if (data[5] != 0)
              data[5]--;

          if (data[1] > 255)
          {
              data[1] = 256;
              data[4] = 0;
              data[6] = 12;
              data[7] = -1;
              data[1] = 0;
              data[0]++;
          }
          SetBgAffine(2, 0x7800, 0x1800, 120, data[4] + 32, data[1], data[1], 0);
          break;
      case 2:
           
          data[1]++;
          SetBgAffine(2, 0x7800, 0x1800, 120, data[4] + 32 + (data[6] >> 2), data[1], data[1], 0);
          data[6] += data[7];
          if (data[6] == 12 || data[6] == -12)
          {
              data[7] *= -1;
              if (data[1] > 295)
              {
                  data[0]++;
                  rt.BeginNormalPaletteFade("PALETTES_ALL", 6, 0, 0x10, "RGB_BLACK");
              }
          }
          break;
      case 3:
           
          data[1] += 16;
          SetBgAffine(2, 0x7800, 0x1800, 120, data[4] + 32, data[1], data[1], 0);
          Task_RayTakesFlightEnd(taskId);
          break;
      }
};

