/** Source: rayquaza_scene.c → Task_TakesFlight_CreateSmoke */
export const Task_TakesFlight_CreateSmoke: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  const data = task.data;
      if ((data[1] & 3) == 0)
      {
          let spriteId = rt.CreateSpriteFromTemplate('sSpriteTemplate_TakesFlight_Smoke', 
                                     (sTakesFlight_SmokeCoords[data[0]][0] * 4) + 120,
                                     (sTakesFlight_SmokeCoords[data[0]][1] * 4) + 80,
                                     0);
          _gs(rt, spriteId).data[0] = (data[0]);
          rt.gba.oam[_gs(rt, spriteId).oamIndex].objMode = ST_OAM_OBJ_BLEND;
          rt.gba.oam[_gs(rt, spriteId).oamIndex].affineMode = ST_OAM_AFFINE_DOUBLE;
          rt.gba.oam[_gs(rt, spriteId).oamIndex].priority = 2;
          InitSpriteAffineAnim(_gs(rt, spriteId));
          if (data[0] == MAX_SMOKE - 1)
          {
              rt.DestroyTask(taskId);
              return;
          }
          else
          {
              data[0]++;
          }
      }

      data[1]++;
};

