/** Source: rayquaza_scene.c → Task_HandleRayDescends */
export const Task_HandleRayDescends: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  const data = task.data;
      switch (data[0])
      {
      case 0:
           
          if (data[1] == 8)
          {
              rt.BeginNormalPaletteFade("PALETTES_ALL", 0, 0x10, 0, "RGB_BLACK");
              data[1] = 0;
              data[0]++;
          }
          else
          {
              data[1]++;
          }
          break;
      case 1:
          if (!rt.gPaletteFade.active)
          {
               
              if (data[1] == 10)
              {
                  data[1] = 0;
                  data[0]++;
                  SetHBlankCallback(HBlankCB_RayDescends);
                  EnableInterrupts(INTR_FLAG_HBLANK | INTR_FLAG_VBLANK);
              }
              else
              {
                  data[1]++;
              }
          }
          break;
      case 2:
           
          if (data[1] == 80)
          {
              data[1] = 0;
              data[0]++;
              CreateDescendsRayquazaSprite();
          }
          else
          {
              data[1]++;
          }
          break;
      case 3:
           
          if (++data[1] == 368)
          {
              data[1] = 0;
              data[0]++;
          }
          break;
      case 4:
           
          rt.BeginNormalPaletteFade("PALETTES_ALL", 0, 0, 0x10, "RGB_BLACK");
          task.func = (t) => Task_RayDescendsEnd(t, rt);
          break;
      }
};

