/** Source: rayquaza_scene.c → Task_HandleRayCharges */
export const Task_HandleRayCharges: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  const data = task.data;
      RayCharges_AnimateBg();
      if ((data[5] & 7) == 0 && data[0] <= 1 && data[1] <= 89)
          /* TODO sound PlaySE */;

      data[5]++;
      switch (data[0])
      {
      case 0:
           
          if (data[1] == 8)
          {
              rt.BeginNormalPaletteFade("PALETTES_ALL", 0, 0x10, 0, "RGB_BLACK");
              data[1] = 0;
              data[0]++;
          }
          else
          {
              data[1]++;
          }
          break;
      case 1:
           
          if (data[1] == 127)
          {
              data[1] = 0;
              data[0]++;
              _gt(rt, data[2]).func = (t) => Task_RayCharges_FlyOffscreen(t, rt);
          }
          else
          {
              data[1]++;
          }
          break;
      case 2:
           
          if (data[1] == 12)
          {
              data[1] = 0;
              data[0]++;
          }
          else
          {
              data[1]++;
          }
          break;
      case 3:
           
          rt.BeginNormalPaletteFade("PALETTES_ALL", 0, 0, 0x10, "RGB_BLACK");
          task.func = (t) => Task_RayChargesEnd(t, rt);
          break;
      }
};

/** Source: rayquaza_scene.c → Task_RayCharges_ShakeRayquaza */
export const Task_RayCharges_ShakeRayquaza: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  const data = task.data;
      if ((data[1] & 3) == 0)
      {
          ChangeBgX(1, (Math.floor(Math.random() * 0x10000) % 8 - 4) << 8, BG_COORD_SET);
          ChangeBgY(1, (Math.floor(Math.random() * 0x10000) % 8 - 4) << 8, BG_COORD_SET);
      }

      data[1]++;
};

/** Source: rayquaza_scene.c → Task_RayCharges_FlyOffscreen */
export const Task_RayCharges_FlyOffscreen: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  const data = task.data;
      if (data[0] == 0)
      {
          ChangeBgX(1, 0, BG_COORD_SET);
          ChangeBgY(1, 0, BG_COORD_SET);
          data[0]++;
          data[1] = 10;
          data[2] = -1;
      }
      else if (data[0] == 1)
      {
          ChangeBgX(1, data[1] << 8, BG_COORD_SUB);
          ChangeBgY(1, data[1] << 8, BG_COORD_ADD);
          data[1] += data[2];
          if (data[1] == -10)
              data[2] *= -1;
      }
};

